/* -------- parser --------
   Grammar:
   expr   := term { ('+'|'-') term }
   term   := factor { '*' factor }
   factor := number
           | variable
           | '(' expr ')'
           | ('+'|'-') factor
*/

static ll vars[VARS];

static void skip_spaces(void) {
    while (*p && isspace((unsigned char)*p)) p++;
}

static ll parse_expr();

static ll parse_number() {
    skip_spaces();
    ll val = 0;
    while (isdigit((unsigned char)*p)) {
        val = val * 10 + (*p - '0');
        p++;
    }
    return val;
}

static ll parse_factor() {
    skip_spaces();

    if (*p == '+') {
        p++;
        return parse_factor();
    }
    if (*p == '-') {
        p++;
        return -parse_factor();
    }
    if (*p == '(') {
        p++;
        ll v = parse_expr();
        skip_spaces();
        if (*p == ')') p++;
        return v;
    }
    if (isdigit((unsigned char)*p)) {
        return parse_number();
    }
    if (*p >= 'a' && *p <= 'z') {
        ll v = vars[*p - 'a'];
        p++;
        return v;
    }

    return 0;
}

static ll parse_term() {
    ll v = parse_factor();
    while (1) {
        skip_spaces();
        if (*p == '*') {
            p++;
            v *= parse_factor();
        } else {
            break;
        }
    }
    return v;
}

static ll parse_expr() {
    ll v = parse_term();
    while (1) {
        skip_spaces();
        if (*p == '+') {
            p++;
            v += parse_term();
        } else if (*p == '-') {
            p++;
            v -= parse_term();
        } else {
            break;
        }
    }
    return v;
}

static ll eval(const char *str) {
    p = str;
    return parse_expr();
}

static void trim_newline(char *s) {
    int n = (int)strlen(s);
    while (n > 0 && (s[n - 1] == '\n' || s[n - 1] == '\r')) {
        s[--n] = '\0';
    }
}

