import sys
from collections import defaultdict

def parse_expression(s):
    """Parse a polynomial expression string into a dict mapping
    tuple of sorted variable powers to coefficient."""
    s = s.replace(' ', '')
    # Add '+' signs for implicit positive at start
    if s[0] not in '+-':
        s = '+' + s
    terms = []
    i = 0
    n = len(s)
    while i < n:
        sign = 1
        if s[i] == '+':
            sign = 1
            i += 1
        elif s[i] == '-':
            sign = -1
            i += 1
        # parse coefficient
        coeff = 0
        if i < n and s[i].isdigit():
            start = i
            while i < n and s[i].isdigit():
                i += 1
            coeff = int(s[start:i])
        else:
            coeff = 1
        coeff *= sign
        # parse variables with exponents
        var_powers = defaultdict(int)
        while i < n and s[i].islower():
            var = s[i]
            i += 1
            exp = 1
            if i < n and s[i] == '^':
                i += 1
                start = i
                while i < n and s[i].isdigit():
                    i += 1
                exp = int(s[start:i])
            var_powers[var] += exp
        terms.append((coeff, tuple(sorted(var_powers.items()))))
    # combine terms
    poly = defaultdict(int)
    for coeff, var_tuple in terms:
        poly[var_tuple] += coeff
    # remove zero coeffs
    return {k: v for k, v in poly.items() if v != 0}

def poly_to_tuple(poly):
    """Convert polynomial dict to a sorted tuple for comparison."""
    return tuple(sorted((vars, coeff) for vars, coeff in poly.items()))

def main():
    data = sys.stdin.read().strip().splitlines()
