import sys
from collections import defaultdict

sys.setrecursionlimit(1_000_000)

class Parser:
    def __init__(self, s):
        self.s = s.replace(" ", "")
        self.n = len(self.s)
        self.i = 0

    def peek(self):
        return self.s[self.i] if self.i < self.n else ''

    def consume(self, ch=None):
        if self.i >= self.n:
            return ''
        c = self.s[self.i]
        if ch is not None and c != ch:
            raise ValueError("Unexpected character")
        self.i += 1
        return c

    def parse(self):
        res = self.parse_expr()
        return res

    def parse_expr(self):
        # expr := term { (+|-) term }
        res = self.parse_term()
        while self.i < self.n and self.peek() in '+-':
            op = self.consume()
            t = self.parse_term()
            if op == '+':
                res = add_poly(res, t)
            else:
                res = sub_poly(res, t)
        return res

    def parse_term(self):
        # term := signed_factor { (*?) signed_factor }
        res = None
        first = True
        while self.i < self.n:
            c = self.peek()
            if c == ')':
                break
            if not first and c in '+-':
                break

            if c == '*':
                self.consume('*')

            f = self.parse_signed_factor()
            if res is None:
                res = f
            else:
                res = mul_poly(res, f)
            first = False

        if res is None:
            return {(): 0}
        return res

    def parse_signed_factor(self):
        sign = 1
        while self.i < self.n and self.peek() in '+-':
            if self.consume() == '-':
                sign *= -1
        f = self.parse_factor()
        if sign == -1:
            f = neg_poly(f)
        return f

    def parse_factor(self):
        c = self.peek()
        if c == '(':
            self.consume('(')
            res = self.parse_expr()
            self.consume(')')
            return res
        elif c.isdigit():
            num = 0
            while self.i < self.n and self.peek().isdigit():
                num = num * 10 + int(self.consume())
            return {(): num}
        elif c.islower():
            v = self.consume()
            return {((v, 1),): 1}
        else:
            raise ValueError("Invalid factor")

def normalize(poly):
    out = {}
    for k, v in poly.items():
        if v != 0:
            out[k] = v
    return out

def add_poly(a, b):
    res = dict(a)
    for k, v in b.items():
        res[k] = res.get(k, 0) + v
        if res[k] == 0:
            del res[k]
    return res

def sub_poly(a, b):
    res = dict(a)
    for k, v in b.items():
        res[k] = res.get(k, 0) - v
        if res[k] == 0:
            del res[k]
    return res

def neg_poly(a):
    return {k: -v for k, v in a.items()}

def mul_mono(m1, m2):
    d = defaultdict(int)
    for v, e in m1:
        d[v] += e
    for v, e in m2:
        d[v] += e
    return tuple(sorted((v, e) for v, e in d.items() if e))

def mul_poly(a, b):
    if not a or not b:
        return {}
    res = {}
    for m1, c1 in a.items():
        if c1 == 0:
            continue
        for m2, c2 in b.items():
            if c2 == 0:
                continue
            m = mul_mono(m1, m2)
            res[m] = res.get(m, 0) + c1 * c2
            if res[m] == 0:
                del res[m]
    return res

def parse_poly(s):
    p = Parser(s).parse()
    return normalize(p)

def main():
    lines = [line.rstrip('\n') for line in sys.stdin if line.strip() != ""]
    if not lines:
        return

    # Common input style for this problem: first line is number of expressions,
    # followed by that many expressions. If not, treat all lines as expressions.
    exprs = None
    if lines[0].isdigit():
