    out = []
    for s in exprs[1:]:
        out.append("yes" if parse_poly(s) == correct else "no")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()

#include <bits/stdc++.h>
using namespace std;

// Evaluate expression modulo several primes to avoid collisions
const vector<int> MODS = {1000000007, 1000000009, 1000000021};
const int K = MODS.size();

// Map variable to its index: a..k -> 0..10
int varIndex(char c) {
    return c - 'a';
}

// Tokenize expression into infix tokens
vector<string> tokenize(const string &s) {
    vector<string> tokens;
    string num;
    for (char c : s) {
        if (isdigit(c) || isalpha(c)) {
            num += c;
        } else {
            if (!num.empty()) {
                tokens.push_back(num);
                num.clear();
            }
            if (c != ' ') {
                tokens.push_back(string(1, c));
            }
        }
    }
    if (!num.empty()) tokens.push_back(num);
    return tokens;
}

// Shunting-yard to get postfix
vector<string> toPostfix(const vector<string> &infix) {
    unordered_map<string, int> prec;
    prec["+"] = 1;
    prec["-"] = 1;
    prec["*"] = 2;

    vector<string> output;
    stack<string> ops;

    for (const string &tok : infix) {
        if (isdigit(tok[0]) || isalpha(tok[0])) {
            output.push_back(tok);
        } else if (tok == "(") {
            ops.push(tok);
        } else if (tok == ")") {
            while (!ops.empty() && ops.top() != "(") {
                output.push_back(ops.top());
                ops.pop();
            }
            if (!ops.empty()) ops.pop(); // pop '('
        } else { // operator
            while (!ops.empty() && ops.top() != "(" && prec[ops.top()] >= prec[tok]) {
                output.push_back(ops.top());
                ops.pop();
            }
            ops.push(tok);
        }
    }
    while (!ops.empty()) {
        output.push_back(ops.top());
        ops.pop();
    }
    return output;
}

// Evaluate postfix with given variable values modulo mod
long long evalPostfix(const vector<string> &postfix, const vector<long long> &varVals, long long mod) {
    stack<long long> st;
    for (const string &tok : postfix) {
        if (isdigit(tok[0])) {
            long long val = 0;
            for (char c : tok) val = (val * 10 + (c - '0')) % mod;
            st.push(val);
        } else if (isalpha(tok[0])) {
            st.push(varVals[varIndex(tok[0])] % mod);
        } else {
            long long b = st.top(); st.pop();
            long long a = st.top(); st.pop();
            if (tok == "+") {
                st.push((a + b) % mod);
            } else if (tok == "-") {
                st.push((a - b + mod) % mod);
            } else if (tok == "*") {
                st.push((a * b) % mod);
            }
        }
    }
    return st.top();
}

// Generate random test points
vector<vector<long long>> generateTestPoints(int numTests, int numVars) {
    vector<vector<long long>> points;
    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
    uniform_int_distribution<long long> dist(0, 1000000000);
    for (int t = 0; t < numTests; t++) {
        vector<long long> vals(numVars);
        for (int i = 0; i < numVars; i++) vals[i] = dist(rng);
        points.push_back(vals);
    }
    return points;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string line;
    // Read first expression (correct answer)
    getline(cin, line);
    string correctExpr = line;

    vector<string> correctTokens = tokenize(correctExpr);
    vector<string> correctPostfix = toPostfix(correctTokens);

    // Identify variables used (a..k)
    set<char> vars;
    for (char c : correctExpr) if (isalpha(c)) vars.insert(c);
    // Also check student expressions later, but we can just assume up to k.
    int numVars = 11; // a to k

    // Generate test points
    int numTests = 20;
    auto testPoints = generateTestPoints(numTests, numVars);

    // Compute correct values at test points for each modulus
    vector<vector<long long>> correctVals(K, vector<long long>(numTests));
    for (int modIdx = 0; modIdx < K; modIdx++) {
        long long mod = MODS[modIdx];
        for (int t = 0; t < numTests; t++) {
            correctVals[modIdx][t] = evalPostfix(correctPostfix, testPoints[t], mod);
        }
    }

    // Process student expressions
    while (getline(cin, line)) {
        if (line.empty()) continue;
        string studentExpr = line;
        vector<string> studentTokens = tokenize(studentExpr);
        vector<string> studentPostfix = toPostfix(studentTokens);

        bool equivalent = true;
        for (int modIdx = 0; modIdx < K && equivalent; modIdx++) {
            long long mod = MODS[modIdx];
            for (int t = 0; t < numTests && equivalent; t++) {
                long long val = evalPostfix(studentPostfix, testPoints[t], mod);
                if (val != correctVals[modIdx][t]) {
                    equivalent = false;
                }
            }
        }
        cout << (equivalent ? "yes" : "no") << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 1e9 + 7;

map<char, ll> vars;
string expr;
int pos;

ll parseExpr();
ll parseTerm();
ll parseFactor();
ll parseBase();

ll parseExpr() {
    ll val = parseTerm();
    while (pos < (int)expr.size() && (expr[pos] == '+' || expr[pos] == '-')) {
        char op = expr[pos++];
        ll t = parseTerm();
        if (op == '+') val = (val + t) % MOD;
        else val = (val - t % MOD + MOD) % MOD;
    }
    return val;
}

ll parseTerm() {
    ll val = parseFactor();
    while (pos < (int)expr.size() && (expr[pos] == '*' || expr[pos] == '/')) {
        char op = expr[pos++];
        ll t = parseFactor();
        if (op == '*') val = val * t % MOD;
        // division not expected for polynomials
    }
    return val;
}

ll parseFactor() {
    ll val = parseBase();
    if (pos < (int)expr.size() && expr[pos] == '^') {
        pos++;
        ll exp = parseBase();
        // compute val^exp mod MOD
        ll result = 1;
        val = ((val % MOD) + MOD) % MOD;
        exp = exp % (MOD - 1); // Fermat's little theorem
        while (exp > 0) {
            if (exp & 1) result = result * val % MOD;
            val = val * val % MOD;
            exp >>= 1;
        }
        return result;
    }
    return val;
}

ll parseBase() {
    if (pos < (int)expr.size() && expr[pos] == '-') {
        pos++;
        return (MOD - parseBase()) % MOD;
    }
    if (pos < (int)expr.size() && expr[pos] == '(') {
        pos++;
        ll val = parseExpr();
        pos++; // ')'
        return val;
    }
    if (pos < (int)expr.size() && isdigit(expr[pos])) {
        ll num = 0;
        while (pos < (int)expr.size() && isdigit(expr[pos]))
            num = num * 10 + (expr[pos++] - '0');
        return num % MOD;
    }
    if (pos < (int)expr.size() && islower(expr[pos])) {
        char c = expr[pos++];
        return vars[c];
    }
    return 0;
}

ll evaluate(const string& s) {
    expr = s;
    pos = 0;
    return parseExpr();
}

