#include <bits/stdc++.h>
using namespace std;

struct Poly {
    // monomial key -> coefficient
    map<string, long long> t;
};

static string trimSpaces(const string& s) {
    string r;
    for (char c : s) if (c != ' ') r += c;
    return r;
}

static string normalizeVars(string v) {
    sort(v.begin(), v.end());
    return v;
}

static Poly makeConst(long long x) {
    Poly p;
    if (x != 0) p.t[""] = x;
    return p;
}

static Poly makeVar(char c) {
    Poly p;
    string s(1, c);
    p.t[s] = 1;
    return p;
}

static void clean(Poly& p) {
    vector<string> del;
    for (auto &kv : p.t) if (kv.second == 0) del.push_back(kv.first);
    for (auto &k : del) p.t.erase(k);
}

static Poly addPoly(const Poly& a, const Poly& b, int sign = 1) {
    Poly r = a;
    for (auto &kv : b.t) {
        r.t[kv.first] += sign * kv.second;
    }
    clean(r);
    return r;
}

static Poly mulPoly(const Poly& a, const Poly& b) {
    Poly r;
    for (auto &x : a.t) {
        for (auto &y : b.t) {
            string key = x.first + y.first;
            key = normalizeVars(key);
            r.t[key] += x.second * y.second;
        }
    }
    clean(r);
    return r;
}

struct Parser {
    string s;
    int n, pos;

    Parser(const string& str) : s(trimSpaces(str)), n((int)s.size()), pos(0) {}

    Poly parseExpression() {
        Poly res = parseTerm();
        while (pos < n && (s[pos] == '+' || s[pos] == '-')) {
            char op = s[pos++];
            Poly rhs = parseTerm();
            if (op == '+') res = addPoly(res, rhs, +1);
            else res = addPoly(res, rhs, -1);
        }
        return res;
    }

    Poly parseTerm() {
        Poly res = parseFactor();
        while (pos < n && s[pos] == '*') {
            ++pos;
            Poly rhs = parseFactor();
            res = mulPoly(res, rhs);
        }
        return res;
    }

    Poly parseFactor() {
        if (pos < n && s[pos] == '(') {
            ++pos;
            Poly inside = parseExpression();
            if (pos < n && s[pos] == ')') ++pos;
            return inside;
        }

        if (pos < n && (s[pos] == '+' || s[pos] == '-')) {
            char op = s[pos++];
            Poly v = parseFactor();
            if (op == '-') {
                Poly z;
                return addPoly(z, v, -1);
            }
            return v;
        }

        if (pos < n && isdigit((unsigned char)s[pos])) {
            long long val = 0;
            while (pos < n && isdigit((unsigned char)s[pos])) {
                val = val * 10 + (s[pos] - '0');
                ++pos;
            }
            return makeConst(val);
        }

        if (pos < n && islower((unsigned char)s[pos])) {
            char c = s[pos++];
            return makeVar(c);
        }

        return Poly();
    }
};

static bool equalPoly(const Poly& a, const Poly& b) {
    return a.t == b.t;
}

