import java.io.*;
import java.util.*;

public class EquivalentExpressions {

    static class Polynomial implements Comparable<Polynomial> {
        Map<String, Integer> terms;

        Polynomial() {
            terms = new HashMap<>();
        }

        Polynomial(String term) {
            terms = new HashMap<>();
            addTerm(term);
        }

        void addTerm(String term) {
            // Parse coefficient and variables
            int coeff = 1;
            int i = 0;
            if (term.charAt(0) == '-') {
                coeff = -1;
                i = 1;
            } else if (term.charAt(0) == '+') {
                i = 1;
            }

            // Find coefficient digits
            int j = i;
            while (j < term.length() && Character.isDigit(term.charAt(j))) {
                j++;
            }
            if (j > i) {
                coeff *= Integer.parseInt(term.substring(i, j));
                i = j;
            }

            // Parse variables with exponents
            StringBuilder varPart = new StringBuilder();
            while (i < term.length()) {
                char c = term.charAt(i);
                if (Character.isLetter(c)) {
                    varPart.append(c);
                    i++;
                    if (i < term.length() && Character.isDigit(term.charAt(i))) {
                        int expStart = i;
                        while (i < term.length() && Character.isDigit(term.charAt(i))) {
                            i++;
                        }
                        int exp = Integer.parseInt(term.substring(expStart, i));
                        for (int k = 1; k < exp; k++) {
                            varPart.append(c);
                        }
                    }
                } else {
                    i++;
                }
            }

            String key = varPart.toString();
            char[] chars = key.toCharArray();
            Arrays.sort(chars);
            key = new String(chars);

            terms.put(key, terms.getOrDefault(key, 0) + coeff);
        }

        void add(Polynomial other) {
            for (Map.Entry<String, Integer> e : other.terms.entrySet()) {
                terms.put(e.getKey(), terms.getOrDefault(e.getKey(), 0) + e.getValue());
            }
        }

        void multiply(Polynomial other) {
            Map<String, Integer> result = new HashMap<>();
            for (Map.Entry<String, Integer> e1 : terms.entrySet()) {
                for (Map.Entry<String, Integer> e2 : other.terms.entrySet()) {
                    String combined = e1.getKey() + e2.getKey();
                    char[] chars = combined.toCharArray();
                    Arrays.sort(chars);
                    String key = new String(chars);
                    int coeff = e1.getValue() * e2.getValue();
                    result.put(key, result.getOrDefault(key, 0) + coeff);
                }
            }
            terms = result;
        }

        Polynomial negate() {
            Polynomial p = new Polynomial();
            for (Map.Entry<String, Integer> e : terms.entrySet()) {
                p.terms.put(e.getKey(), -e.getValue());
            }
            return p;
        }

        void removeZeroTerms() {
            terms.entrySet().removeIf(e -> e.getValue() == 0);
        }

        @Override
        public boolean equals(Object o) {
            if (!(o instanceof Polynomial)) return false;
            Polynomial p = (Polynomial) o;
            removeZeroTerms();
            p.removeZeroTerms();
            return terms.equals(p.terms);
        }

        @Override
        public int compareTo(Polynomial o) {
            return 0;
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        String correctExpr = br.readLine().trim();
        Polynomial correct = parseExpression(correctExpr);

        for (int i = 0; i < n; i++) {
            String studentExpr = br.readLine().trim();
            Polynomial student = parseExpression(studentExpr);
            System.out.println(correct.equals(student) ? "yes" : "no");
        }
    }

    static Polynomial parseExpression(String expr) {
        // Remove spaces
        expr = expr.replaceAll("\\s+", "");
        // Handle implicit multiplication: e.g., "2x" -> "2*x", but careful with parentheses
        expr = insertImplicitMultiplication(expr);
        return evaluate(expr);
    }

    static String insertImplicitMultiplication(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (i > 0) {
                char prev = s.charAt(i-1);
                // number/variable followed by '(' or variable/number
                if ((Character.isDigit(prev) || Character.isLetter(prev) || prev == ')') &&
                    (c == '(' || Character.isLetter(c))) {
                    sb.append('*');
                }
            }
            sb.append(c);
        }
        return sb.toString();
    }

    static int index;
    static String expr;

    static Polynomial evaluate(String e) {
        expr = e;
        index = 0;
        return parseAddSub();
    }

    static Polynomial parseAddSub() {
        Polynomial result = parseMulDiv();
        while (index < expr.length() && (expr.charAt(index) == '+' || expr.charAt(index) == '-')) {
            char op = expr.charAt(index);
            index++;
            Polynomial next = parseMulDiv();
            if (op == '+') {
                result.add(next);
            } else {
                result.add(next.negate());
            }
        }
        return result;
    }

    static Polynomial parseMulDiv() {
        Polynomial result = parseUnary();
        while (index < expr.length() && expr.charAt(index) == '*') {
            index++;
            Polynomial next = parseUnary();
            result.multiply(next);
        }
        return result;
    }

    static Polynomial parseUnary() {
        if (index < expr.length() && expr.charAt(index) == '-') {
            index++;
            Polynomial p = parsePrimary();
            return p.negate();
        }
        return parsePrimary();
    }

    static Polynomial parsePrimary() {
        if (expr.charAt(index) == '(') {
            index++; // skip '('
            Polynomial p = parseAddSub();
            index++; // skip ')'
            return p;
        }
        // parse a term like 2x^2y or -3 or x
        int start = index;
        while (index < expr.length() && (Character.isDigit(expr.charAt(index)) || Character.isLetter(expr.charAt(index)))) {
            index++;
        }
        String term = expr.substring(start, index);
        return new Polynomial(term);
    }
}

import java.util.*;
import java.io.*;

public class Main {
    static long MOD = 1_000_000_007L;
    static Map<Character, Long> vars;
    static String expr;
    static int pos;

    static long parseExpr() {
        long val = parseTerm();
        while (pos < expr.length() && (expr.charAt(pos) == '+' || expr.charAt(pos) == '-')) {
            char op = expr.charAt(pos++);
            long t = parseTerm();
            val = op == '+' ? (val + t) % MOD : (val - t + MOD) % MOD;
        }
        return val;
    }

    static long parseTerm() {
        long val = parseFactor();
        while (pos < expr.length() && expr.charAt(pos) == '*') {
            pos++;
            val = val * parseFactor() % MOD;
        }
        return val;
    }

    static long parseFactor() {
        long val = parseBase();
        if (pos < expr.length() && expr.charAt(pos) == '^') {
            pos++;
            long exp = parseBase(); // exponent should be non-negative integer
            val = modpow(val, exp, MOD);
        }
        return val;
    }

    static long parseBase() {
        if (pos < expr.length() && expr.charAt(pos) == '-') {
            pos++;
            return (MOD - parseFactor()) % MOD;
        }
        if (pos < expr.length() && expr.charAt(pos) == '(') {
            pos++;
            long val = parseExpr();
            pos++; // ')'
            return val;
        }
        if (pos < expr.length() && Character.isLetter(expr.charAt(pos))) {
            return vars.get(expr.charAt(pos++));
        }
        // number
        long num = 0;
        while (pos < expr.length() && Character.isDigit(expr.charAt(pos))) {
            num = (num * 10 + (expr.charAt(pos++) - '0')) % MOD;
        }
        return num;
    }

    static long modpow(long base, long exp, long mod) {
        long result = 1; base %= mod;
        while (exp > 0) { if ((exp & 1) == 1) result = result * base % mod; base = base * base % mod; exp >>= 1; }
        return result;
    }

    static long evaluate(String e, Map<Character, Long> v) {
        expr = e.replaceAll("\\s+", ""); vars = v; pos = 0;
        return parseExpr();
    }

import java.io.*;
import java.util.*;

public class Main {
    // Polynomial represented as: monomialKey -> coefficient
    // monomialKey is variables sorted alphabetically, e.g. "aabz", "" for constant
    static class Poly {
        HashMap<String, Long> map = new HashMap<>();

        Poly() {}

        static Poly constant(long v) {
            Poly p = new Poly();
            if (v != 0) p.map.put("", v);
            return p;
        }

        static Poly variable(char c) {
            Poly p = new Poly();
            p.map.put(String.valueOf(c), 1L);
            return p;
        }

        Poly add(Poly other) {
            Poly res = new Poly();
            for (Map.Entry<String, Long> e : this.map.entrySet()) {
                res.map.put(e.getKey(), e.getValue());
            }
            for (Map.Entry<String, Long> e : other.map.entrySet()) {
                res.map.merge(e.getKey(), e.getValue(), Long::sum);
                if (res.map.get(e.getKey()) == 0) res.map.remove(e.getKey());
            }
            return res;
        }

        Poly sub(Poly other) {
            Poly res = new Poly();
            for (Map.Entry<String, Long> e : this.map.entrySet()) {
                res.map.put(e.getKey(), e.getValue());
            }
            for (Map.Entry<String, Long> e : other.map.entrySet()) {
                res.map.merge(e.getKey(), -e.getValue(), Long::sum);
                if (res.map.get(e.getKey()) == 0) res.map.remove(e.getKey());
            }
            return res;
        }

        Poly mul(Poly other) {
            Poly res = new Poly();
            for (Map.Entry<String, Long> a : this.map.entrySet()) {
                for (Map.Entry<String, Long> b : other.map.entrySet()) {
                    String key = mergeVars(a.getKey(), b.getKey());
                    long val = a.getValue() * b.getValue();
                    res.map.merge(key, val, Long::sum);
                    if (res.map.get(key) == 0) res.map.remove(key);
                }
            }
            return res;
        }

        @Override
        public boolean equals(Object o) {
            if (!(o instanceof Poly)) return false;
            Poly p = (Poly) o;
            return map.equals(p.map);
        }

        static String mergeVars(String a, String b) {
            int i = 0, j = 0;
            StringBuilder sb = new StringBuilder(a.length() + b.length());
            while (i < a.length() && j < b.length()) {
                if (a.charAt(i) <= b.charAt(j)) sb.append(a.charAt(i++));
                else sb.append(b.charAt(j++));
            }
            while (i < a.length()) sb.append(a.charAt(i++));
            while (j < b.length()) sb.append(b.charAt(j++));
            return sb.toString();
        }
    }

    static class Parser {
        String s;
        int pos, n;

        Parser(String s) {
            this.s = s.replaceAll("\\s+", "");
            this.n = this.s.length();
            this.pos = 0;
        }

        Poly parse() {
            Poly p = expr();
            return p;
        }

        // expr := term (('+'|'-') term)*
        Poly expr() {
            Poly res = term();
            while (pos < n) {
                char c = s.charAt(pos);
                if (c == '+') {
                    pos++;
                    res = res.add(term());
                } else if (c == '-') {
                    pos++;
                    res = res.sub(term());
                } else break;
            }
            return res;
        }

        // term := factor ( '*'? factor )*
        // implicit multiplication allowed
        Poly term() {
            Poly res = factor();
            while (pos < n) {
                char c = s.charAt(pos);
                if (c == '*') {
                    pos++;
                    res = res.mul(factor());
                } else if (c == '(' || Character.isLowerCase(c) || Character.isDigit(c)) {
                    res = res.mul(factor());
                } else {
                    break;
                }
            }
            return res;
        }

        // factor := number | variable | '(' expr ')' | ('+'|'-') factor
        Poly factor() {
            if (pos < n) {
                char c = s.charAt(pos);
                if (c == '+') {
                    pos++;
                    return factor();
                }
                if (c == '-') {
                    pos++;
                    return Poly.constant(0).sub(factor());
                }
                if (c == '(') {
                    pos++;
                    Poly inside = expr();
                    if (pos < n && s.charAt(pos) == ')') pos++;
                    return inside;
                }
                if (Character.isDigit(c)) {
                    long val = 0;
                    while (pos < n && Character.isDigit(s.charAt(pos))) {
                        val = val * 10 + (s.charAt(pos) - '0');
                        pos++;
                    }
                    return Poly.constant(val);
                }
                if (Character.isLowerCase(c)) {
                    pos++;
                    return Poly.variable(c);
                }
            }
            return Poly.constant(0);
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            if (!line.trim().isEmpty()) lines.add(line.trim());
        }

        if (lines.isEmpty()) return;

        int start = 0;
        int m;
        try {
            m = Integer.parseInt(lines.get(0));
            start = 1;
        } catch (Exception e) {
            m = lines.size();
            start = 0;
        }

        if (start >= lines.size()) return;

        Poly correct = new Parser(lines.get(start)).parse();
        StringBuilder out = new StringBuilder();

        for (int i = start + 1; i < Math.min(start + m, lines.size()); i++) {
            Poly student = new Parser(lines.get(i)).parse();
            out.append(correct.equals(student) ? "yes" : "no").append('\n');
        }

        System.out.print(out.toString());
    }
}
